int compat_sys_waitid(int which, compat_pid_t pid, struct compat_siginfo __user *infop, int options, struct compat_rusage __user *uru)
{
    struct compat_siginfo si;
    int ret;

    ret = kernel_waitid(which, pid, &si, options, uru);
    if (ret < 0)
        return ret;

    if (infop) {
        if (access_ok(VERIFY_WRITE, infop, sizeof(*infop))) {
            if (copy_to_user(infop, &si, sizeof(si)))
                return -EFAULT;
        } else {
            return -EFAULT;
        }
    }

    return 0;
}

