int compat_waitid_syscall(int which, compat_pid_t pid,
                          struct compat_siginfo __user *infop,
                          int options, struct compat_rusage __user *uru) {
    struct siginfo si;
    int ret;

    ret = kernel_waitid(which, pid, &si, options, uru);
    if (ret < 0)
        return ret;

    if (infop && copy_siginfo_to_user(infop, &si)) {
        return -EFAULT;
    }

    return 0;
}
